'use strict';
// Text-only coaching: no generated people, poses or schematic figures.
// Exact IDs avoid applying a movement's instructions to a different variant.
// Each entry: IDs, quick cue, start, three steps, two common mistakes, easier option.
const EXERCISE_GUIDES=[
 [['squat','dbsquat','goblet'],'Keep your heels down and let your knees follow your toes.','Stand with feet about shoulder-width apart. Hold any goblet weight close to your chest.',['Bend your knees and hips together.','Lower through a comfortable range with your whole foot on the floor.','Push through your feet to stand tall.'],['Do not let your knees collapse inward.','Do not force extra depth by lifting your heels.'],'Use a shallower bodyweight squat near a stable support.'],
 [['rdl','kbrdl'],'Push your hips back and keep the weight close to your legs.','Stand with slightly bent knees and the weight in front of your thighs.',['Push your hips backward with only a small knee bend.','Lower until you feel tension behind your thighs and can still keep your back steady.','Bring your hips forward to stand upright.'],['Do not turn the movement into a deep squat.','Stop before your back rounds; reaching the floor is not the goal.'],'Practice moving your hips backward without a weight first.'],
 [['bodyhinge'],'Move from your hips while keeping your back steady.','Stand with feet hip-width apart and knees slightly bent.',['Push your hips backward.','Tip your torso forward only as far as you can keep your back steady.','Bring your hips forward and stand tall.'],['Do not round your back to reach lower.','Avoid leaning backward at the top.'],'Use a smaller range and practice slowly.'],
 [['dbpress','kbpress'],'Lower gently to the floor, then press without bouncing.','Lie on your back with bent knees and feet flat. Hold the weight above your chest, wrists over elbows.',['Lower slowly with elbows comfortably angled away from your torso.','Let the upper arm touch the floor gently.','Press up; for the one-arm version, complete the target on each side.'],['Do not bounce your upper arms off the floor.','Avoid bending your wrists backward.'],'Choose a lighter weight.'],
 [['ohp','kbohp'],'Press overhead without leaning back.','Stand tall with the weight at shoulder level and your trunk gently braced.',['Press overhead through a comfortable path.','Keep your ribs over your pelvis and breathe freely.','Lower slowly to shoulder level; complete both sides for a per-side target.'],['Do not arch your lower back to push the weight up.','Do not force a painful overhead range.'],'Use a lighter weight and a comfortable range.'],
 [['kneepush'],'Keep a straight line from your knees to your shoulders.','Place hands slightly wider than shoulders and knees on the floor, hips in line with your torso.',['Bend your elbows to lower your chest.','Keep your trunk steady as you approach the floor.','Push through your hands to return.'],['Do not leave your hips behind as your chest lowers.','Avoid flaring elbows straight out to the sides.'],'Try wall press-ups.'],
 [['pushup'],'Lower your whole body together and push back up.','Place hands slightly wider than shoulders and balance on your toes, body in a straight line.',['Bend your elbows and lower your chest with control.','Keep your hips in line with shoulders and ankles.','Push through your hands to return.'],['Do not let your lower back sag.','Do not lead with your head.'],'Use kneeling push-ups or wall press-ups.'],
 [['dbrow','kbrow'],'Draw your elbow toward your hip without twisting.','Hinge at the hips with a steady back. Hold the weight in one hand; use stable support with the other if needed.',['Pull the weight toward your hip, elbow close to your body.','Pause briefly without rotating your torso.','Lower slowly, then complete the target on the other side.'],['Do not jerk the weight upward with your whole body.','Avoid shrugging your shoulder toward your ear.'],'Reduce the weight and use stable support.'],
 [['curl'],'Keep your upper arms still and lower slowly.','Stand tall with a weight in each hand, palms forward and elbows near your sides.',['Bend your elbows to lift the weights.','Keep your torso still as the weights approach your shoulders.','Lower with control to the start.'],['Do not swing your back to lift the weights.','Avoid letting your elbows drift forward.'],'Use lighter weights.'],
 [['dbextension','kbtri'],'Keep your upper arms steady while your elbows bend.','Hold one light weight securely with both hands overhead. Keep ribs down and feet steady.',['Bend your elbows to lower the weight behind your head.','Stop at a comfortable depth with upper arms steady.','Straighten your elbows to lift the weight again.'],['Do not arch your back to lift the weight.','Avoid a weight you cannot hold securely overhead.'],'Start with a lighter weight.'],
 [['lateral'],'Lift light weights out to the sides without shrugging.','Stand tall with light weights by your sides and elbows softly bent.',['Raise your arms out to the sides.','Stop at or below shoulder height in a comfortable range.','Lower slowly without swinging.'],['Do not shrug to raise the weights.','Avoid using momentum from your legs or torso.'],'Practice without weights first.'],
 [['bridge'],'Lift your hips without arching your lower back.','Lie on your back with bent knees and feet flat, about hip-width apart.',['Gently brace and press through your feet.','Lift your hips until shoulders, hips and knees form a comfortable line.','Lower your hips slowly to the floor.'],['Do not lift higher by arching your back.','Do not let your knees fall inward.'],'Use a smaller lifting range.'],
 [['sideleg'],'Lift the top leg while keeping your hips stacked.','Lie on your side with your head supported and hips stacked. Bend the lower leg for balance if needed.',['Keep the top leg straight and lift it gently.','Stop before your pelvis rolls backward.','Lower slowly, then complete the target on the other side.'],['Do not roll your torso backward.','Do not swing your leg upward.'],'Lift through a smaller range.'],
 [['calf','dbcalf','kbcalf','singlecalf'],'Rise onto the balls of your feet and lower your heels slowly.','Stand on a flat floor near stable support. Use it for balance and hold any weight securely.',['Raise your heels by pressing through the balls of your feet.','Pause briefly with ankles steady.','Lower slowly; for the single-leg version, complete both sides.'],['Do not bounce at the bottom.','Avoid rolling onto the outside edges of your feet.'],'Use both legs, no added weight and stable support.'],
 [['deadbug'],'Reach opposite arm and leg away while keeping your lower back steady.','Lie on your back with arms pointing up and hips and knees bent to about right angles.',['Gently brace while breathing normally.','Reach one arm and the opposite leg away; stop before your back arches.','Return to the start and switch sides.'],['Do not let your lower back lift as you reach.','Avoid rushing the change of sides.'],'Move one leg at a time and shorten the reach.'],
 [['birddog'],'Reach long without lifting your arm or leg too high.','Start on hands and knees, hands under shoulders and knees under hips.',['Gently brace your trunk.','Reach one arm forward and the opposite leg backward, hips level.','Return slowly, then switch sides.'],['Do not twist your pelvis toward the ceiling.','Do not arch your back to lift your leg higher.'],'Move just one arm or one leg at a time.'],
 [['plank'],'Keep a steady body line and breathe throughout the hold.','Place forearms on the floor, elbows under shoulders. Extend your legs and balance on your toes.',['Gently brace and lift your hips into line.','Hold while breathing steadily.','Lower your knees when you can no longer keep the position.'],['Do not let your hips sag.','Do not hold your breath to extend the hold.'],'Rest your knees on the floor and use a shorter hold.'],
 [['prone'],'Lift your bent arms gently; keep your neck relaxed.','Lie face down with forehead comfortably supported and elbows bent into a W.',['Keep chest and hips resting on the floor.','Lift hands and elbows slightly, gently drawing shoulder blades together.','Lower slowly and relax before repeating.'],['Do not lift your chest by arching your back.','Avoid pulling shoulders toward your ears.'],'Use a very small lift without added weight.'],
 [['pronet'],'Lift your arms gently out to the sides without shrugging.','Lie face down with forehead supported and arms out to the sides in a T.',['Keep your trunk resting on the floor.','Lift your arms slightly, gently drawing shoulder blades together.','Lower slowly to the floor.'],['Do not arch your back to lift higher.','Avoid shrugging shoulders toward your ears.'],'Reduce the lifting range and use no added weight.'],
 [['reverseangel'],'Sweep your arms slowly through a comfortable range.','Lie face down with forehead supported and arms alongside your body.',['Keep your torso resting on the floor.','Gently lift and sweep your arms toward overhead only as far as comfortable.','Sweep your arms back toward your sides with control.'],['Do not force a painful shoulder range.','Avoid lifting your chest to compensate.'],'Use a smaller sweep and keep the movement slow.']
];
const guideById=new Map(EXERCISE_GUIDES.flatMap(([ids,cue,start,steps,mistakes,easier])=>ids.map(id=>[id,{cue,start,steps,mistakes,easier}])));
function exerciseGuideData(m){
 if(!m)return null;const known=MOVES[m.id]||Object.values(MOVES).find(x=>x.name===m.name);
 // Respect coaching edited by the user.
 return known&&(!m.description||m.description===known.description)?guideById.get(known.id)||null:null;
}
function quickMovementCue(m){return exerciseGuideData(m)?.cue||m?.description||'';}
function movementGuide(m){
 if(!m)return '';m=reviewedMovement(m);const g=exerciseGuideData(m);
 const list=(items,tag)=>`<${tag}>${items.map(text=>`<li>${esc(text)}</li>`).join('')}</${tag}>`;
 return `<section class="movement-coaching" aria-label="Exercise instructions"><h4>Purpose & equipment</h4><p>${esc(groupLabel(m))} · ${esc(equipmentCaption(m))}</p>${g?`<h4>Starting position</h4><p>${esc(g.start)}</p><h4>Three steps</h4>${list(g.steps,'ol')}<h4>Watch for these mistakes</h4>${list(g.mistakes,'ul')}`:`<h4>How to move</h4><p>${esc(m.description)}</p>`}<h4>Target & counting</h4><p>${esc(targetCaption(m))}</p><p class="counting-help">${esc(countingHint(m))}</p><h4>Weight & progression</h4><p>${m.loadDependent?'Choose a weight that leaves about 2–3 controlled reps in reserve. When every set is comfortable at the upper end of the target, increase by the smallest available weight step.':'Keep the movement controlled. When every set is comfortable at the upper end of the target, choose a slightly harder version or a longer hold within the suggested range.'}</p><p>Keep breathing. Stop the set when you can no longer maintain the position or movement.</p>${g?`<h4>Easier option</h4><p>${esc(g.easier)}</p>`:''}<details class="demonstration-sources"><summary>Demonstrations & examples</summary><p>Open the source and choose the matching exercise and equipment. Examples may show a different variant.</p><a href="https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/strength-training/art-20046031" target="_blank" rel="noopener noreferrer">Mayo Clinic: strength exercise videos</a><a href="https://www.nhs.uk/live-well/exercise/strength-exercises/" target="_blank" rel="noopener noreferrer">NHS: illustrated beginner exercises</a><p class="small muted">External English-language sources · internet required. The written instructions above work offline. Opening instructions does not pause your workout.</p></details></section>`;
}
function exerciseInstructionPanel(m){return m?`<details class="exercise-instructions"><summary>How to do this exercise</summary>${movementGuide(m)}</details>`:'';}
